create table public.avuhz_assessment_access_proposals (assessment_access_proposal_id uuid primary key, tenant_id uuid not null, engagement_id uuid not null, diagnostic_scope_id uuid not null, scope_version integer not null check (scope_version>=1), canonical_scope_digest text not null check (canonical_scope_digest ~ '^sha256:[0-9a-f]{64}$'), assessment_access_authority_digest text not null check (assessment_access_authority_digest ~ '^sha256:[0-9a-f]{64}$'), action_set_version integer not null check (action_set_version>=1), diagnostic_agreement_authority_id uuid not null, diagnostic_agreement_authority_version integer not null check (diagnostic_agreement_authority_version>=1), diagnostic_payment_verification_id uuid not null, diagnostic_payment_verification_version integer not null check (diagnostic_payment_verification_version>=1), target_system_references jsonb not null check (jsonb_typeof(target_system_references)='array' and jsonb_array_length(target_system_references)>=1), permitted_actions text[] not null check (cardinality(permitted_actions)>=1 and permitted_actions <@ array['VIEW_CONFIGURATION','VIEW_OPERATIONAL_STATE','VIEW_LOGS','VIEW_METRICS','VIEW_ACCESS_CONFIGURATION','VIEW_NETWORK_CONFIGURATION','VIEW_SECURITY_CONFIGURATION','VIEW_COMPLIANCE_EVIDENCE','NON_DESTRUCTIVE_CONNECTIVITY_TEST','NON_DESTRUCTIVE_PERMISSION_TEST']::text[]), status text not null check (status in ('OPEN','SUPERSEDED','WITHDRAWN','CONSUMED')), consumed_at timestamptz, record_version integer not null check (record_version>=1), created_at timestamptz not null default now(), unique (tenant_id,assessment_access_proposal_id), check ((status<>'CONSUMED' or consumed_at is not null)), check ((status='CONSUMED' or consumed_at is null)), foreign key (tenant_id,engagement_id) references public.avuhz_engagements (tenant_id,engagement_id), foreign key (tenant_id,diagnostic_scope_id,scope_version) references public.avuhz_diagnostic_scopes (tenant_id,diagnostic_scope_id,scope_version), foreign key (tenant_id,diagnostic_agreement_authority_id) references public.avuhz_diagnostic_agreement_authorities (tenant_id,diagnostic_agreement_authority_id), foreign key (tenant_id,diagnostic_payment_verification_id) references public.avuhz_diagnostic_payment_verifications (tenant_id,diagnostic_payment_verification_id)); create table public.avuhz_assessment_access_grants (assessment_access_grant_id uuid primary key, tenant_id uuid not null, engagement_id uuid not null, source_assessment_access_proposal_id uuid not null, source_assessment_access_proposal_version integer not null check (source_assessment_access_proposal_version>=1), diagnostic_scope_id uuid not null, scope_version integer not null check (scope_version>=1), canonical_scope_digest text not null check (canonical_scope_digest ~ '^sha256:[0-9a-f]{64}$'), assessment_access_authority_digest text not null check (assessment_access_authority_digest ~ '^sha256:[0-9a-f]{64}$'), action_set_version integer not null check (action_set_version>=1), diagnostic_agreement_authority_id uuid not null, diagnostic_agreement_authority_version integer not null check (diagnostic_agreement_authority_version>=1), diagnostic_payment_verification_id uuid not null, diagnostic_payment_verification_version integer not null check (diagnostic_payment_verification_version>=1), target_system_references jsonb not null check (jsonb_typeof(target_system_references)='array' and jsonb_array_length(target_system_references)>=1), permitted_actions text[] not null check (cardinality(permitted_actions)>=1 and permitted_actions <@ array['VIEW_CONFIGURATION','VIEW_OPERATIONAL_STATE','VIEW_LOGS','VIEW_METRICS','VIEW_ACCESS_CONFIGURATION','VIEW_NETWORK_CONFIGURATION','VIEW_SECURITY_CONFIGURATION','VIEW_COMPLIANCE_EVIDENCE','NON_DESTRUCTIVE_CONNECTIVITY_TEST','NON_DESTRUCTIVE_PERMISSION_TEST']::text[]), status text not null check (status in ('APPROVED','ACTIVE','EXPIRED','REVOKED','CLOSED')), approved_at timestamptz not null, verified_at timestamptz, active_from timestamptz, expires_at timestamptz, revoked_at timestamptz, closed_at timestamptz, closure_reason text check (closure_reason is null or closure_reason='AGREEMENT_ENDED'), record_version integer not null check (record_version>=1), created_at timestamptz not null default now(), unique (tenant_id,assessment_access_grant_id), unique (tenant_id,source_assessment_access_proposal_id), check (status<>'APPROVED' or (verified_at is null and active_from is null and expires_at is null)), check (status not in ('ACTIVE','EXPIRED') or (verified_at is not null and active_from=verified_at and expires_at>active_from)), check (status not in ('REVOKED','CLOSED') or verified_at is null or (active_from=verified_at and expires_at>active_from)), check ((status='REVOKED')=(revoked_at is not null)), check ((status='CLOSED')=(closed_at is not null)), foreign key (tenant_id,engagement_id) references public.avuhz_engagements (tenant_id,engagement_id), foreign key (tenant_id,source_assessment_access_proposal_id) references public.avuhz_assessment_access_proposals (tenant_id,assessment_access_proposal_id), foreign key (tenant_id,diagnostic_scope_id,scope_version) references public.avuhz_diagnostic_scopes (tenant_id,diagnostic_scope_id,scope_version), foreign key (tenant_id,diagnostic_agreement_authority_id) references public.avuhz_diagnostic_agreement_authorities (tenant_id,diagnostic_agreement_authority_id), foreign key (tenant_id,diagnostic_payment_verification_id) references public.avuhz_diagnostic_payment_verifications (tenant_id,diagnostic_payment_verification_id));
